using System;
using System.Collections.Generic;
using System.Reflection;
namespace Downfield {
public static class DefenseBalanceTests {
 static int checks,failures;
 static void Check(bool ok,string label){checks++;if(!ok){failures++;Console.WriteLine("FAIL Defensive balance: "+label);}}
 public class Sample {public int TD,Catches,First,Sacks,Picks;public float Yards;}
 public static Franchise Club(int rating){Franchise f=Franchise.Create(new Profile(),new Roster());if(rating>0){foreach(ClubPlayer p in f.Players)if(p.Team==f.UserTeam&&p.Slot>=0&&p.Slot<11)p.OVR=p.Speed=p.Power=p.Hands=rating;f.Passing=3;f.Running=2;f.Club.CoachOff=1;}return f;}
 static void Healthy(Franchise f){foreach(ClubPlayer p in f.Players){p.InjuryWeeks=0;p.InjuryType="";}}
 public static int OpenReceiver(Simulation s){int best=0;float score=-999;for(int i=0;i<5;i++){Player r=s.Receiver(i);if(!r.Active)continue;float gap=99;foreach(Player d in s.Players)if(d.Team==1&&d.Active&&d.KnockTime<=0)gap=Math.Min(gap,Simulation.Distance(r.X,r.Z,d.X,d.Z));float value=gap+Math.Min(25,r.Z-s.Spot)*.08f;if(value>score){score=value;best=i;}}return best;}
 static void Verticals(Simulation s){s.CustomPlay=new DrawnPlay();for(int i=0;i<5;i++){DrawnRoute route=new DrawnRoute();route.Receiver=i;route.Points.Add(new RouteNode(s.Receiver(i).X,45));s.CustomPlay.Routes.Add(route);}s.UseCustom=true;}
 public static Sample Trials(int rating,int play,bool custom,int delay,bool read,int count){Franchise f=Club(rating);Sample result=new Sample();for(int seed=0;seed<count;seed++){Healthy(f);Simulation s=new Simulation(51000+seed);f.Apply(s,1+seed%11);s.Playbook=play;s.RunPlay=Simulation.IsRunCall(play);s.NewGame();if(custom)Verticals(s);s.Snap();bool threw=false;for(int frame=0;frame<1320&&(s.State==Phase.Live||s.State==Phase.Flight||s.State==Phase.Loose);frame++){float x=0,z=0;s.Sprint=true;if(s.RunPlay||s.Completions>0||s.Controlled.Role!="QB"){z=1;if(play==10)x=s.Controlled.X<22?.9f:0;if(play==11)x=s.Controlled.X>-22?-.9f:0;}else if(!threw&&frame>=delay&&s.CanThrow){s.BeginPass(read?OpenReceiver(s):1);s.Charge=.35f;s.ReleasePass();threw=true;}s.Update(1f/60,x,z);}result.TD+=s.Touchdowns>0?1:0;result.First+=s.Touchdowns>0||s.TotalYards>=10?1:0;result.Catches+=s.Completions;result.Sacks+=s.Sacks;result.Picks+=s.Interceptions;result.Yards+=s.Touchdowns>0?80:s.TotalYards;}Console.WriteLine("Rated offense "+(rating==0?"starter":rating.ToString())+" / "+(custom?"drawn verticals":play.ToString())+": TD "+result.TD+"/"+count+", catches "+result.Catches+", first downs "+result.First+", avg yards "+(result.Yards/count).ToString("F1"));return result;}
 public static Simulation WholeGame(int rating,int seed,bool onside){Franchise f=Club(rating);Simulation s=new Simulation(81000+seed);f.Apply(s,1+seed%11);s.Playbook=2;s.NewGame();int playFrame=0;for(int frame=0;frame<50000&&s.State!=Phase.GameOver;frame++){if(s.AmbulanceActive){s.SkipAmbulance();continue;}if(s.State==Phase.PreSnap){playFrame=0;s.Playbook=2;s.RunPlay=false;s.Snap();}else if(s.State==Phase.Conversion)s.ChooseConversion(false);else if(s.State==Phase.Kick&&!s.KickAnimating){s.KickMeter=.5f;s.StopKick();}else if(s.State==Phase.Kickoff){if(onside){s.RequestOnsideTry();if(s.OnsideRulesPending)s.ConfirmOnsideTry();}else s.NormalKickoff();}else if(s.State==Phase.Dead||s.State==Phase.Halftime||s.State==Phase.Opponent)s.Next();else{float z=0;if(s.State==Phase.Live){playFrame++;if(s.CanThrow){if(playFrame>=135){s.BeginPass(OpenReceiver(s));s.Charge=.35f;s.ReleasePass();}}else if(!s.HandoffPending)z=1;}s.Sprint=true;s.Update(1f/60,0,z);}}return s;}
 static object Field(Simulation s,string name){return typeof(Simulation).GetField(name,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(s);}
 public static int Run(){checks=failures=0;
  // An audible changes offense only: AI cannot read the newly selected play before the snap.
  Simulation a=new Simulation(721),b=new Simulation(721);a.Playbook=2;b.Playbook=10;b.RunPlay=true;bool same=true;for(int i=11;i<22;i++)if(a.Players[i].X!=b.Players[i].X||a.Players[i].Z!=b.Players[i].Z)same=false;Check(same&&a.Coverage==b.Coverage,"defense does not peek at a presnap audible");
  int held=0,carried=0;for(int seed=0;seed<80;seed++){Simulation s=new Simulation(51000+seed);s.Playbook=2;foreach(Player p in s.Players)if(p.Role=="DL"||p.Role=="LB")p.Active=false;s.Snap();for(int n=0;n<45;n++)s.Update(1f/60,0,0);if(s.Coverage!="ROBBER"&&s.Players[20].Z>=s.Spot+15&&s.Players[21].Z>=s.Spot+15)held++;for(int n=0;n<135&&s.State==Phase.Live;n++)s.Update(1f/60,0,0);if(s.Players[19].Z>s.Spot+16&&s.Players[19].AimZ>s.Spot+18)carried++;}Check(held>50,"safeties hold depth while early routes develop");Check(carried>40,"slot coverage carries a vertical release beyond the shallow zone");
  // A lone safety starts wide and ahead. A pursuit angle must beat a straight sprint without teleporting.
  int angledStops=0;bool bounded=true;for(int seed=0;seed<40;seed++){Simulation s=new Simulation(62000+seed);foreach(Player p in s.Players)p.Active=false;Player runner=s.Players[1],safety=s.Players[20];runner.Active=safety.Active=true;runner.X=0;runner.Z=40;runner.Speed=9;runner.HasBall=true;runner.OVR=85;safety.X=7;safety.Z=50;safety.Speed=8;safety.OVR=80;safety.BlockPartner=-1;s.Controlled=runner;s.State=Phase.Live;s.Sprint=true;for(int n=0;n<900&&s.State==Phase.Live;n++){float x=safety.X,z=safety.Z;s.Update(1f/60,0,1);if(safety.KnockTime<=0&&Simulation.Distance(x,z,safety.X,safety.Z)>.4f)bounded=false;}if(s.Touchdowns==0&&s.State!=Phase.Live)angledStops++;}Check(angledStops>30,"safety takes an angle rather than losing a diagonal footrace");Check(bounded,"pursuit stays within grounded movement speed");
  Simulation chase=new Simulation(42);foreach(Player p in chase.Players)p.Active=false;Player back=chase.Players[1],slow=chase.Players[20];back.Active=slow.Active=true;back.X=slow.X=0;back.Z=45;slow.Z=10;back.HasBall=true;back.Speed=9;slow.Speed=6;chase.Controlled=back;chase.State=Phase.Live;chase.Sprint=true;for(int i=0;i<180;i++)chase.Update(1f/60,0,1);Check(back.Z-slow.Z>35&&slow.Speed==6,"slow defenders get no hidden catch-up speed");
  Sample mid=Trials(85,2,false,135,false,80),elite=Trials(95,2,false,135,false,80);
  Check(mid.TD<=12,"decent signings cannot turn repeated verticals into routine 80-yard TDs");Check(mid.Catches>25&&mid.First>25,"decent receivers still complete deep throws and earn first downs");Check(elite.TD<=24,"elite verticals still face deep help");Check(elite.Yards>mid.Yards+400,"elite speed and hands retain a meaningful advantage");
  Sample custom=Trials(85,2,true,135,true,80),customElite=Trials(95,2,true,135,true,80);
  Check(custom.TD<=16&&customElite.TD<=24,"drawn vertical routes cannot bypass coverage");Check(custom.Catches>35&&customElite.Catches>50,"drawn routes remain useful against the defense");
  Sample shortPass=Trials(85,0,false,90,true,80),mesh=Trials(85,14,false,90,true,80),wheel=Trials(95,16,false,90,true,80);
  Check(shortPass.Catches>=40&&shortPass.First>=15,"short throws and timing remain productive");Check(mesh.Catches>=35&&mesh.Yards>300,"crossing routes still offer catches and run after catch");Check(wheel.TD<=22,"wheel routes do not leave the safety frozen in a fixed landmark");
  Sample runs=Trials(95,10,false,0,false,80);Check(runs.TD<10&&runs.Yards>200,"upgraded runners gain ground without automatic sideline TDs");
  int[] totals=new int[4],peaks=new int[4];bool finished=true,learned=false,varied=false;int index=0;foreach(int rating in new int[]{85,95})foreach(bool onside in new bool[]{false,true}){HashSet<string> covers=new HashSet<string>();for(int seed=0;seed<30;seed++){Simulation s=WholeGame(rating,seed,onside);totals[index]+=s.HomeScore;peaks[index]=Math.Max(peaks[index],s.HomeScore);finished&=s.State==Phase.GameOver;learned|=(int)Field(s,"recentDeep")>=3;covers.Add(s.Coverage);if(seed==0){s.NewGame();Check((int)Field(s,"recentDeep")==0&&((Queue<int>)Field(s,"offensiveHistory")).Count==0,"new game clears learned tendencies / "+rating+" / "+onside);}}varied|=covers.Count>=5;Console.WriteLine("Full games "+rating+" / "+(onside?"onside every TD":"normal kickoff")+": avg "+(totals[index]/30f).ToString("F1")+", peak "+peaks[index]+" in 30 games");index++;}
  Check(finished,"all 120 full-game probes finish through halves, injuries, PATs and turnovers");Check(learned&&varied,"defense learns repeated deep throws while keeping varied calls");Check(totals[0]/30f<22&&totals[1]/30f<30,"decent rosters cannot farm routine scores with repeated deep balls");Check(totals[2]/30f<36&&totals[3]/30f<45&&peaks[3]<100,"elite offense no longer farms 100-point games in the repeated-play probe");
  Console.WriteLine("Defensive balance: "+checks+" checks, "+failures+" failures");return failures;
 }
}
}
